INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-as201', 'stk-abdulla_yahia', 'AS 201', 'doc', '{"docs": [{"id": "stk-dr-m68472", "n": "Dr. Stephen Binns", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. ستيفن بينز ]\n\nAS 201 - Term 141\n- التحضير : يومياً ، ينادي بالأسماء …\n\n- طريقة الشرح : يشرح على السبورة - شرحه ممتاز و متمكن جداً في الماث ، بس عيبه أنه ما يحل أمثلة كثير + غير منظم بعض الشيء في الكتابة …\n\n- الكويزات : أعطانا كويز واحد مستواه متوسط من النوت اللي يكتبه في الشرح …\n\n- المياجر : متوسطة …\n\n- الفاينلات : أعطانا فاينل جزء منه تيك هوم و كان متوسط و الجزء الثاني في الكلاس و كان أقل من المتوسط …\n\n- القريد النهائي : B+\n\n- الصوت : واضح و ممتاز …\n\n- إضافات : الدكتور محترم و عقلية ممتازة + تصحيحه جيد …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422204-as201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stephen-binns/68472/50", "user": "Abdulla_Yahia", "ts": 1422222585000, "tid": 68472, "pn": 50}}]}', 1422222585000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-q18-as201', 'stk-q18', 'AS 201', 'doc', '{"docs": [{"id": "stk-dr-m68577", "n": "Dr. Mohammad Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "AS-201\n211\n- التحضير : ينادي بالأسماء بداية الكلاس واللي يتأخر يرسله تيمز+جات أيام كنا ندخل رابط ونكتب كود ولخبطة بس بطل ورجع للتحضير التقليدي.\n\n- طريقة الشرح : يقرأ اللي بالكتاب ويكتبه بالسبورة ولو سألته يحاول يجاوبك بس غالبا بتضيع ربي يعينك.\n\n- الكويزات : الكويزات كانت وسط وكنا نأجل فيها براحتنا الصدق.\n\n- المياجر والفاينلات: للأسف كانت صعبة جدا لحد أنه الأفرج مره قال لنا أنه حول 50% وهو داف بالتصحيح يعني كان تقريبا 40% وتوقعنا الفاينل يكون سهل وكان نفس الشي.\n\n- القريد النهائي :C\n\n- الصوت : صعب فهمه نسبيا الا لو كنت قدام ومركز.\n\n- إضافات : الدكتور تحسه طيب بس مع ذلك شديد بشكل غريب وهو مايعتبر متخصص عشان كذه جالس يضيع الكل معاه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533388-as201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-omar/68577/27", "user": "Q18", "ts": 1641836070000, "tid": 68577, "pn": 27}}]}', 1641836070000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
